var lvl=new FilteredElementCollector(doc).OfClass(typeof(Level)).Cast<Level>().First(l=>l.Name==Tama.Args.Get(args,"level","Level 2"));
string lib=app.GetLibraryPaths().Where(k=>k.Key.Contains("Metric")).Select(k=>k.Value).FirstOrDefault()??"";
var loadLog=new List<string>();
foreach(var o in (object[])args["familyCandidates"]){ var rel=o.ToString(); Family fam=null;
  try{ bool ok=doc.LoadFamily(lib+rel, out fam); if(ok) loadLog.Add("loaded "+rel);}catch(Exception){ }
}
doc.Regenerate();
var syms=new FilteredElementCollector(doc).OfClass(typeof(FamilySymbol)).Cast<FamilySymbol>().ToList();
var doorCat=(int)BuiltInCategory.OST_Doors;
var doorSyms=syms.Where(s=>s.Category!=null&&s.Category.Id.IntegerValue==doorCat).ToList();
FamilySymbol baseSingle=doorSyms.First(s=>s.FamilyName=="M_Single-Flush");
FamilySymbol baseSlide=doorSyms.FirstOrDefault(s=>s.FamilyName.ToLower().Contains("slid"));
FamilySymbol baseBifold=doorSyms.FirstOrDefault(s=>s.FamilyName.ToLower().Contains("bifold")||s.FamilyName.ToLower().Contains("bi-fold"));
FamilySymbol baseDouble=doorSyms.FirstOrDefault(s=>s.FamilyName.ToLower().Contains("double"));
FamilySymbol baseWin=syms.First(s=>s.FamilyName=="M_Fixed");
var cache=new Dictionary<string,FamilySymbol>();
Func<FamilySymbol,double,double,FamilySymbol> sized=(b,w,h)=>{
  string n="BC "+w+" x "+h+"mm"; string key=b.FamilyName+"|"+n; if(cache.ContainsKey(key)) return cache[key];
  var ex=new FilteredElementCollector(doc).OfClass(typeof(FamilySymbol)).Cast<FamilySymbol>().FirstOrDefault(s=>s.FamilyName==b.FamilyName&&s.Name==n);
  if(ex==null){ ex=(FamilySymbol)b.Duplicate(n);
    var pw=ex.get_Parameter(BuiltInParameter.DOOR_WIDTH)??ex.get_Parameter(BuiltInParameter.WINDOW_WIDTH)??ex.LookupParameter("Width");
    var ph=ex.get_Parameter(BuiltInParameter.DOOR_HEIGHT)??ex.get_Parameter(BuiltInParameter.WINDOW_HEIGHT)??ex.LookupParameter("Height");
    if(pw!=null&&!pw.IsReadOnly) pw.Set(w/304.8); if(ph!=null&&!ph.IsReadOnly) ph.Set(h/304.8);}
  if(!ex.IsActive) ex.Activate(); cache[key]=ex; return ex;};
var walls=new FilteredElementCollector(doc).OfClass(typeof(Wall)).Cast<Wall>().Where(w=>w.LevelId==lvl.Id && w.Location is LocationCurve).ToList();
Func<double,double,string,Wall> host=(x,y,dir)=>{ Wall best=null; double bd=1e9; var p=new XYZ(x,y,lvl.Elevation);
  foreach(var w in walls){ var c=((LocationCurve)w.Location).Curve as Line; if(c==null) continue; var d=c.Direction;
    bool isV=Math.Abs(d.Y)>0.9; if((dir=="V")!=isV) continue;
    var a=c.GetEndPoint(0); double t=(p-a).DotProduct(d); if(t< -0.01||t>c.Length+0.01) continue;
    var r=c.Project(p); if(r==null) continue;
    double dist=r.Distance; double tol=w.Width/2+0.2; if(dist<tol&&dist<bd){bd=dist;best=w;} }
  return best; };
Func<string,XYZ> vec=s=>s=="+X"?XYZ.BasisX:s=="-X"?-XYZ.BasisX:s=="+Y"?XYZ.BasisY:s=="-Y"?-XYZ.BasisY:null;
var placed=new List<object>(); var skipped=new List<object>(); var fallback=new List<string>();
double dh=Tama.Args.Get(args,"doorHeight",2100.0);
foreach(var o in (object[])args["doors"]){ var a=(object[])o;
  double x=Convert.ToDouble(a[0]),y=Convert.ToDouble(a[1]),w=Convert.ToDouble(a[2]); string dir=a[3].ToString(), sw=a[4].ToString(), hg=a[5].ToString(), kind=a[6].ToString(), id=a[7].ToString();
  var hw=host(x/304.8,y/304.8,dir); if(hw==null){ skipped.Add(new{id,reason="no host wall"}); continue; }
  FamilySymbol b=baseSingle; string note="";
  if(kind=="sliding"){ if(baseSlide!=null) b=baseSlide; else note="PLACEHOLDER: sliding door family not loaded"; }
  else if(kind=="cupboard"&&w>1000){ if(baseBifold!=null) b=baseBifold; else if(baseDouble!=null) b=baseDouble; else note="PLACEHOLDER: cupboard/bifold family not loaded"; }
  else if(kind=="double"){ if(baseDouble!=null) b=baseDouble; else note="PLACEHOLDER: double door family not loaded"; }
  else if(kind=="lift") note="Lift landing door (placeholder)";
  var s=sized(b,w,dh);
  var pr=((LocationCurve)hw.Location).Curve.Project(new XYZ(x/304.8,y/304.8,lvl.Elevation)).XYZPoint;
  var fi=doc.Create.NewFamilyInstance(new XYZ(pr.X,pr.Y,lvl.Elevation),s,hw,lvl,Autodesk.Revit.DB.Structure.StructuralType.NonStructural);
  doc.Regenerate();
  var sv=vec(sw); if(sv!=null && fi.FacingOrientation.DotProduct(sv)>0 && fi.CanFlipFacing) fi.flipFacing();
  fi.get_Parameter(BuiltInParameter.ALL_MODEL_INSTANCE_COMMENTS).Set("Block C | "+id+" | swing "+sw+" hinge "+hg+(note!=""?" | "+note:""));
  if(note.StartsWith("PLACEHOLDER")) fallback.Add(id);
  placed.Add(new{id,elementId=fi.Id.IntegerValue});
}
double sill=Tama.Args.Get(args,"sillHeight",900.0), wh=Tama.Args.Get(args,"windowHeight",1500.0);
foreach(var o in (object[])args["windows"]){ var a=(object[])o;
  double x=Convert.ToDouble(a[0]),y=Convert.ToDouble(a[1]),w=Convert.ToDouble(a[2]); string dir=a[3].ToString(), id=a[4].ToString();
  var hw=host(x/304.8,y/304.8,dir); if(hw==null){ skipped.Add(new{id,reason="no host wall"}); continue; }
  var s=sized(baseWin,w,wh);
  var pr=((LocationCurve)hw.Location).Curve.Project(new XYZ(x/304.8,y/304.8,lvl.Elevation)).XYZPoint;
  var fi=doc.Create.NewFamilyInstance(new XYZ(pr.X,pr.Y,lvl.Elevation),s,hw,lvl,Autodesk.Revit.DB.Structure.StructuralType.NonStructural);
  var sp=fi.get_Parameter(BuiltInParameter.INSTANCE_SILL_HEIGHT_PARAM); if(sp!=null&&!sp.IsReadOnly) sp.Set(sill/304.8);
  fi.get_Parameter(BuiltInParameter.ALL_MODEL_INSTANCE_COMMENTS).Set("Block C | "+id);
  placed.Add(new{id,elementId=fi.Id.IntegerValue});
}
return new{loadLog,families=new{slide=baseSlide!=null?baseSlide.FamilyName:null,bifold=baseBifold!=null?baseBifold.FamilyName:null,dbl=baseDouble!=null?baseDouble.FamilyName:null},placed=placed.Count,skipped,fallbackCount=fallback.Count,types=cache.Keys.ToList()};
